1	"use client";
2	
3	import { useEffect } from "react";
4	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	import { useAuth } from "@/hooks/useAuth";
7	
8	export type TaskStatus = "todo" | "in_progress" | "done";
9	export type TaskPriority = "low" | "medium" | "high";
10	
11	export interface Task {
12	  id: string;
13	  team_id: string;
14	  title: string;
15	  description: string | null;
16	  assigned_to: string | null;
17	  created_by: string;
18	  related_entity_type: string | null;
19	  related_entity_id: string | null;
20	  status: TaskStatus;
21	  priority: TaskPriority;
22	  due_date: string | null;
23	  completed_at: string | null;
24	  created_at: string;
25	  updated_at: string;
26	}
27	
28	export function useTasks(teamId: string | null) {
29	  const { user } = useAuth();
30	  const queryClient = useQueryClient();
31	  const queryKey = ["tasks", teamId];
32	
33	  const { data: tasks = [], isLoading, error } = useQuery<Task[]>({
34	    queryKey,
35	    queryFn: async () => {
36	      if (!teamId) return [];
37	      const { data, error } = await (supabase as any)
38	        .from("tasks")
39	        .select("*")
40	        .eq("team_id", teamId)
41	        .order("created_at", { ascending: false });
42	      if (error) throw error;
43	      return data ?? [];
44	    },
45	    enabled: !!teamId,
46	    staleTime: 30_000,
47	  });
48	
49	  // Realtime
50	  useEffect(() => {
51	    if (!teamId) return;
52	    const channel = supabase
53	      .channel(`tasks-${teamId}`)
54	      .on(
55	        "postgres_changes",
56	        {
57	          event: "*",
58	          schema: "public",
59	          table: "tasks",
60	          filter: `team_id=eq.${teamId}`,
61	        },
62	        () => {
63	          queryClient.invalidateQueries({ queryKey });
64	        }
65	      )
66	      .subscribe();
67	    return () => {
68	      supabase.removeChannel(channel);
69	    };
70	  }, [teamId, queryClient]);
71	
72	  const createTask = useMutation({
73	    mutationFn: async (task: {
74	      title: string;
75	      description?: string;
76	      assigned_to?: string;
77	      job_id?: string;
78	      candidate_id?: string;
79	      priority?: TaskPriority;
80	      due_date?: string;
81	    }) => {
82	      const { job_id, candidate_id, ...rest } = task;
83	      const { error } = await (supabase as any).from("tasks").insert({
84	        team_id: teamId,
85	        created_by: user?.id,
86	        related_entity_type: job_id ? "job" : candidate_id ? "candidate" : null,
87	        related_entity_id: job_id ?? candidate_id ?? null,
88	        ...rest,
89	      });
90	      if (error) throw error;
91	    },
92	    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
93	  });
94	
95	  const updateTask = useMutation({
96	    mutationFn: async ({ id, ...updates }: Partial<Task> & { id: string }) => {
97	      const payload: Record<string, unknown> = { ...updates };
98	      if (updates.status === "done" && !updates.completed_at) {
99	        payload.completed_at = new Date().toISOString();
100	      }
101	      if (updates.status && updates.status !== "done") {
102	        payload.completed_at = null;
103	      }
104	      const { error } = await (supabase as any)
105	        .from("tasks")
106	        .update(payload)
107	        .eq("id", id);
108	      if (error) throw error;
109	    },
110	    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
111	  });
112	
113	  const deleteTask = useMutation({
114	    mutationFn: async (id: string) => {
115	      const { error } = await (supabase as any)
116	        .from("tasks")
117	        .delete()
118	        .eq("id", id);
119	      if (error) throw error;
120	    },
121	    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
122	  });
123	
124	  return { tasks, isLoading, error, createTask, updateTask, deleteTask };
125	}
