1	"use client";
2	
3	import { useEffect } from "react";
4	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	import { toast } from "sonner";
7	
8	// ─── Types ────────────────────────────────────────────────────────────────────
9	
10	export interface PipelineStage {
11	  id: string;
12	  team_id: string;
13	  name: string;
14	  color: string;
15	  sort_order: number;
16	  is_default: boolean;
17	  created_at: string;
18	}
19	
20	export interface PipelineStageWithRejected extends PipelineStage {
21	  synthetic?: boolean;
22	}
23	
24	// Default stages used as fallback when no team or no custom stages configured
25	export const DEFAULT_STAGES: PipelineStage[] = [
26	  { id: "default-applied",   team_id: "", name: "Applied",   color: "#6b7280", sort_order: 0, is_default: true, created_at: "" },
27	  { id: "default-screened",  team_id: "", name: "Screened",  color: "#3b82f6", sort_order: 1, is_default: true, created_at: "" },
28	  { id: "default-interview", team_id: "", name: "Interview", color: "#8b5cf6", sort_order: 2, is_default: true, created_at: "" },
29	  { id: "default-offer",     team_id: "", name: "Offer",     color: "#f59e0b", sort_order: 3, is_default: true, created_at: "" },
30	  { id: "default-hired",     team_id: "", name: "Hired",     color: "#10b981", sort_order: 4, is_default: true, created_at: "" },
31	];
32	
33	const REJECTED_STAGE: PipelineStageWithRejected = {
34	  id: "synthetic-rejected",
35	  team_id: "",
36	  name: "Rejected",
37	  color: "#ef4444",
38	  sort_order: 999,
39	  is_default: false,
40	  created_at: "",
41	  synthetic: true,
42	};
43	
44	// ─── Fetch ───────────────────────────────────────────────────────────────────
45	
46	async function fetchStages(teamId: string): Promise<PipelineStage[]> {
47	  try {
48	    const { data, error } = await (supabase as any)
49	      .from("pipeline_stages")
50	      .select("*")
51	      .eq("team_id", teamId)
52	      .order("sort_order", { ascending: true });
53	
54	    if (error) {
55	      if (
56	        error.message?.includes("schema cache") ||
57	        error.message?.includes("does not exist") ||
58	        error.code === "42P01"
59	      ) {
60	        return [];
61	      }
62	      throw error;
63	    }
64	    return (data ?? []) as PipelineStage[];
65	  } catch (err: unknown) {
66	    const e = err as { message?: string };
67	    if (e?.message?.includes("schema cache") || e?.message?.includes("does not exist")) {
68	      return [];
69	    }
70	    throw err;
71	  }
72	}
73	
74	// ─── usePipelineStages ───────────────────────────────────────────────────────
75	
76	export function usePipelineStages(teamId: string | null | undefined) {
77	  const queryClient = useQueryClient();
78	
79	  const query = useQuery({
80	    queryKey: ["pipeline-stages", teamId],
81	    queryFn: () => fetchStages(teamId!),
82	    enabled: !!teamId,
83	    staleTime: 60_000,
84	    retry: false,
85	  });
86	
87	  // Realtime subscription — keeps stages in sync when another admin edits
88	  useEffect(() => {
89	    if (!teamId) return;
90	
91	    const channel = supabase
92	      .channel(`pipeline-stages-${teamId}`)
93	      .on(
94	        "postgres_changes",
95	        { event: "*", schema: "public", table: "pipeline_stages", filter: `team_id=eq.${teamId}` },
96	        () => {
97	          queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
98	        }
99	      )
100	      .subscribe();
101	
102	    return () => {
103	      supabase.removeChannel(channel);
104	    };
105	  }, [teamId, queryClient]);
106	
107	  const rawStages: PipelineStage[] =
108	    query.data && query.data.length > 0 ? query.data : (teamId ? [] : DEFAULT_STAGES);
109	
110	  // Always fall back to DEFAULT_STAGES if loaded but empty
111	  const baseStages: PipelineStage[] =
112	    !teamId ? DEFAULT_STAGES : query.data && query.data.length > 0 ? query.data : DEFAULT_STAGES;
113	
114	  // Append synthetic Rejected entry
115	  const stagesWithRejected: PipelineStageWithRejected[] = [...baseStages, REJECTED_STAGE];
116	
117	  return {
118	    ...query,
119	    stages: baseStages,
120	    stagesWithRejected,
121	    rawStages,
122	  };
123	}
124	
125	// ─── CRUD Mutations ───────────────────────────────────────────────────────────
126	
127	export function useCreatePipelineStage(teamId: string) {
128	  const queryClient = useQueryClient();
129	
130	  return useMutation({
131	    mutationFn: async (input: { name: string; color: string }) => {
132	      // Determine next sort_order
133	      const existing = queryClient.getQueryData<PipelineStage[]>(["pipeline-stages", teamId]) ?? [];
134	      const maxOrder = existing.reduce((m, s) => Math.max(m, s.sort_order), -1);
135	
136	      const { data, error } = await (supabase as any)
137	        .from("pipeline_stages")
138	        .insert({ team_id: teamId, name: input.name, color: input.color, sort_order: maxOrder + 1 })
139	        .select()
140	        .single();
141	
142	      if (error) throw error;
143	      return data as PipelineStage;
144	    },
145	    onSuccess: () => {
146	      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
147	      toast.success("Stage created");
148	    },
149	    onError: (err: Error) => {
150	      toast.error(err.message ?? "Failed to create stage");
151	    },
152	  });
