31	export function useTeamDashboard(teamId: string | null) {
32	  return useQuery<TeamDashboardData>({
33	    queryKey: ["team-dashboard", teamId],
34	    queryFn: async () => {
35	      if (!teamId) {
36	        return {
37	          totalJobs: 0,
38	          activeCandidates: 0,
39	          pendingTasks: 0,
40	          memberCount: 0,
41	          recentActivity: [],
42	          tasksByAssignee: [],
43	          recruiterActivity: [],
44	        };
45	      }
46	
47	      const [
48	        jobsRes,
49	        pendingTasksRes,
50	        membersRes,
51	        activityRes,
52	        allTasksRes,
53	      ] = await Promise.all([
54	        // Total jobs for this team
55	        (supabase as any)
56	          .from("jobs")
57	          .select("id", { count: "exact", head: true })
58	          .eq("team_id", teamId),
59	
60	        // Pending tasks count
61	        (supabase as any)
62	          .from("tasks")
63	          .select("id", { count: "exact", head: true })
64	          .eq("team_id", teamId)
65	          .neq("status", "done"),
66	
67	        // Team members count
68	        (supabase as any)
69	          .from("team_members")
70	          .select("id", { count: "exact", head: true })
71	          .eq("team_id", teamId),
72	
73	        // Last 5 activity items
74	        (supabase as any)
75	          .from("activity_log")
76	          .select("*")
77	          .eq("team_id", teamId)
78	          .order("created_at", { ascending: false })
79	          .limit(5),
80	
81	        // All tasks for assignee summary (limited columns)
82	        (supabase as any)
83	          .from("tasks")
84	          .select("assigned_to, status")
85	          .eq("team_id", teamId)
86	          .not("assigned_to", "is", null),
87	      ]);
88	
89	      // Active candidates: count resumes linked to this team's jobs
90	      // We fetch job IDs first, then count resumes
91	      let activeCandidates = 0;
92	      const { data: jobIds } = await (supabase as any)
93	        .from("jobs")
94	        .select("id")
95	        .eq("team_id", teamId);
96	
97	      const teamJobIds =
98	        (jobIds as { id: string }[] | null)?.map((j) => j.id) ?? [];
99	
100	      if (teamJobIds.length > 0) {
101	        const { count } = await (supabase as any)
102	          .from("resumes")
103	          .select("id", { count: "exact", head: true })
104	          .in("job_id", teamJobIds);
105	        activeCandidates = count ?? 0;
106	      }
107	
108	      // ── Recruiter Activity (last 14 days) ───────────────────────────
109	      // Four parallel aggregate queries — stage moves, notes, completed tasks, activity count
110	      const fourteenDaysAgo = new Date(
111	        Date.now() - 14 * 24 * 60 * 60 * 1000
112	      ).toISOString();
113	
114	      const [stageMovesRes, notesRes, completedTasksRes, activity14dRes] =
115	        await Promise.all([
116	          teamJobIds.length
117	            ? (supabase as any)
118	                .from("stage_history")
119	                .select("changed_by")
120	                .in("job_id", teamJobIds)
121	                .gte("changed_at", fourteenDaysAgo)
122	                .not("changed_by", "is", null)
123	            : Promise.resolve({ data: [] }),
124	          teamJobIds.length
125	            ? (supabase as any)
126	                .from("candidate_notes")
127	                .select("author_id")
128	                .in("job_id", teamJobIds)
129	                .gte("created_at", fourteenDaysAgo)
130	                .not("author_id", "is", null)
131	            : Promise.resolve({ data: [] }),
132	          (supabase as any)
133	            .from("tasks")
134	            .select("assigned_to")
135	            .eq("team_id", teamId)
136	            .eq("status", "done")
137	            .gte("updated_at", fourteenDaysAgo)
138	            .not("assigned_to", "is", null),
139	          (supabase as any)
140	            .from("activity_log")
141	            .select("actor_id")
142	            .eq("team_id", teamId)
143	            .gte("created_at", fourteenDaysAgo)
144	            .not("actor_id", "is", null),
145	        ]);
146	
147	      const recruiterMap = new Map<string, RecruiterActivityRow>();
148	      const ensureRow = (userId: string): RecruiterActivityRow => {
149	        let row = recruiterMap.get(userId);
150	        if (!row) {
151	          row = {
152	            user_id: userId,
153	            stage_moves: 0,
154	            notes_authored: 0,
155	            tasks_completed: 0,
156	            activity_14d: 0,
157	          };
158	          recruiterMap.set(userId, row);
159	        }
160	        return row;
161	      };
162	
163	      ((stageMovesRes.data ?? []) as { changed_by: string }[]).forEach((r) => {
164	        if (r.changed_by) ensureRow(r.changed_by).stage_moves += 1;
165	      });
166	      ((notesRes.data ?? []) as { author_id: string }[]).forEach((r) => {
167	        if (r.author_id) ensureRow(r.author_id).notes_authored += 1;
168	      });
169	      ((completedTasksRes.data ?? []) as { assigned_to: string }[]).forEach(
170	        (r) => {
171	          if (r.assigned_to) ensureRow(r.assigned_to).tasks_completed += 1;
172	        }
173	      );
174	      ((activity14dRes.data ?? []) as { actor_id: string }[]).forEach((r) => {
175	        if (r.actor_id) ensureRow(r.actor_id).activity_14d += 1;
176	      });
177	
178	      const recruiterActivity = Array.from(recruiterMap.values()).sort(
179	        (a, b) => b.activity_14d - a.activity_14d
180	      );
181	
182	      // Build tasks-by-assignee summary
183	      const tasksByAssignee: TasksByAssignee[] = [];
184	      const allTasks = (allTasksRes.data ?? []) as { assigned_to: string; status: string }[];
185	      const assigneeMap = new Map<string, TasksByAssignee>();
186	
187	      for (const t of allTasks) {
188	        if (!t.assigned_to) continue;
189	        if (!assigneeMap.has(t.assigned_to)) {
190	          assigneeMap.set(t.assigned_to, { user_id: t.assigned_to, pending: 0, completed: 0 });
191	        }
192	        const entry = assigneeMap.get(t.assigned_to)!;
193	        if (t.status === "done") {
194	          entry.completed += 1;
195	        } else {
196	          entry.pending += 1;
197	        }
198	      }
199	      assigneeMap.forEach((v) => tasksByAssignee.push(v));
