10	
11	export interface OutreachEvent {
12	  id: string;
13	  kind: OutreachKind;
14	  to: string;
15	  subject: string | null;
16	  body: string | null;
17	  status: OutreachStatus;
18	  sent_at: string;
19	  sender_user_id: string | null;
20	  error: string | null;
21	}
22	
23	interface OutreachLogRow {
24	  id: string;
25	  type: string | null;
26	  to_address: string | null;
27	  subject: string | null;
28	  status: string | null;
29	  sent_at: string | null;
30	  user_id: string | null;
31	}
32	
33	interface SmsLogRow {
34	  id: string;
35	  to_phone: string;
36	  message: string | null;
37	  status: string | null;
38	  created_at: string | null;
39	  user_id: string | null;
40	  error: string | null;
41	}
