43	// ─── Normalizers ────────────────────────────────────────────────────────────
44	
45	function normalizeStatus(raw: string | null | undefined): OutreachStatus {
46	  if (raw === "failed") return "failed";
47	  if (raw === "pending") return "pending";
48	  return "sent";
49	}
50	
51	function fromOutreachLog(row: OutreachLogRow): OutreachEvent {
52	  return {
53	    id: `email:${row.id}`,
54	    kind: "email",
55	    to: row.to_address ?? "",
56	    subject: row.subject ?? null,
57	    body: null,
58	    status: normalizeStatus(row.status),
59	    sent_at: row.sent_at ?? new Date(0).toISOString(),
60	    sender_user_id: row.user_id ?? null,
61	    error: null,
62	  };
63	}
64	
65	function fromSmsLog(row: SmsLogRow): OutreachEvent {
66	  return {
67	    id: `sms:${row.id}`,
68	    kind: "sms",
69	    to: row.to_phone,
70	    subject: null,
71	    body: row.message ?? null,
72	    status: normalizeStatus(row.status),
73	    sent_at: row.created_at ?? new Date(0).toISOString(),
74	    sender_user_id: row.user_id ?? null,
75	    error: row.error ?? null,
76	  };
77	}
