79	// ─── Hook ────────────────────────────────────────────────────────────────────
80	
81	/**
82	 * Fetches every outreach event for a candidate — emails (`outreach_log`)
83	 * and SMS (`sms_logs`) merged into a single timeline sorted by most recent.
84	 */
85	export function useOutreachHistory(resumeId: string | null) {
86	  return useQuery<OutreachEvent[]>({
87	    queryKey: ["outreach-history", resumeId],
88	    queryFn: async () => {
89	      if (!resumeId) return [];
90	
91	      const [emailsRes, smsRes] = await Promise.all([
92	        (supabase as any)
93	          .from("outreach_log")
94	          .select("id, type, to_address, subject, status, sent_at, user_id")
95	          .eq("resume_id", resumeId)
96	          .order("sent_at", { ascending: false }),
97	        (supabase as any)
98	          .from("sms_logs")
99	          .select("id, to_phone, message, status, created_at, user_id, error")
100	          .eq("resume_id", resumeId)
101	          .order("created_at", { ascending: false }),
102	      ]);
103	
104	      const emails = ((emailsRes.data ?? []) as OutreachLogRow[]).map(fromOutreachLog);
105	      const sms = ((smsRes.data ?? []) as SmsLogRow[]).map(fromSmsLog);
106	
107	      const merged = [...emails, ...sms];
108	      merged.sort((a, b) => (a.sent_at < b.sent_at ? 1 : -1));
109	      return merged;
110	    },
111	    enabled: !!resumeId,
112	    staleTime: 60_000,
113	  });
